WITH valid AS (SELECT *, CONCAT(dept_name, ', ', location) AS dept_name_location, CASE WHEN dept_name IN ('Marketing', 'Sales') THEN 'Group A' ELSE 'Other' END AS dept_name_group, COALESCE(dept_name, 'UNKNOWN') AS dept_name_clean FROM departments WHERE dept_name = 'Legal') SELECT location, STDDEV_SAMP(budget) AS budget_stddev, COUNT(*) AS event_count, COUNT(*) FILTER (WHERE dept_name = 'Marketing') AS marketing_rows, COUNT_IF(dept_name = 'Legal') AS legal_events, COUNT(*) AS row_count FROM valid GROUP BY location ORDER BY location DESC NULLS LAST;
